referenceSolutions.javascript:
export function solve(base, requests) {
  return requests.map(
    (r) =>
      base +
      r.path +
      (r.query.length
        ? "?" +
          r.query.map(([k, v]) => encodeURIComponent(k) + "=" + encodeURIComponent(v)).join("&")
        : ""),
  );
}

